// The data URL already contains every byte, so `/1.1` classifies this as an
// inline non-capability rather than borrowing filesystem or network authority.
export async function pull() {
  try {
    const m = await import("data:text/javascript,export const v = 42;");
    return "pulled " + m.v;
  } catch (e) {
    return "denied: " + e.name;
  }
}
